package com.storemate.backend.web;
import com.storemate.backend.domain.*;import com.storemate.backend.repo.*;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import tools.jackson.databind.ObjectMapper;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/stores/{storeId}/work/sessions/{sessionId}/breaks") public class WorkBreakController {
 private final StoreAccess access;private final WorkSessionRepository sessions;private final StoreMemberRepository members;private final PayrollStatementRepository statements;private final StockBatchService locks;private final ObjectMapper json;
 public WorkBreakController(StoreAccess access,WorkSessionRepository sessions,StoreMemberRepository members,PayrollStatementRepository statements,StockBatchService locks,ObjectMapper json){this.access=access;this.sessions=sessions;this.members=members;this.statements=statements;this.locks=locks;this.json=json;}
 public record Save(long revision,List<StatutoryPayCalculator.Pause> breaks){}
 public record Breaks(long revision,long seconds,String clockIn,String clockOut,List<StatutoryPayCalculator.Pause> breaks){}
 private WorkSession record(Account actor,Long sid,Long id){Store s=access.requireMember(actor,sid);return sessions.findById(id).filter(w->w.getStore().getId().equals(sid)&&(w.getAccount().getId().equals(actor.getId())||s.getOwner().getId().equals(actor.getId()))).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"본인 또는 소속 직원의 근무 기록을 선택해주세요"));}
 private Breaks view(WorkSession w){try{var list=w.getBreaksJson()==null?List.<StatutoryPayCalculator.Pause>of():Arrays.asList(json.readValue(w.getBreaksJson(),StatutoryPayCalculator.Pause[].class));return new Breaks(w.getBreakRevision(),w.getBreakSeconds(),w.getClockIn().toString(),w.getClockOut()==null?null:w.getClockOut().toString(),list);}catch(Exception e){throw new IllegalStateException(e);}}
 @GetMapping @Transactional(readOnly=true) public Breaks get(@RequestAttribute(AuthInterceptor.ACCOUNT)Account actor,@PathVariable Long storeId,@PathVariable Long sessionId){return view(record(actor,storeId,sessionId));}
 @PutMapping @Transactional public Breaks put(@RequestAttribute(AuthInterceptor.ACCOUNT)Account actor,@PathVariable Long storeId,@PathVariable Long sessionId,@RequestBody Save r){var w=record(actor,storeId,sessionId);locks.lock(w.getStore());w=sessions.findLockedById(sessionId).orElseThrow();var member=members.findByAccountAndStore(w.getAccount(),w.getStore()).orElseThrow();if(statements.findByMemberAndPeriod(member,YearMonth.from(w.getClockIn()).toString()).isPresent())throw new ApiException(HttpStatus.CONFLICT,"확정한 급여월의 휴게시간은 변경할 수 없어요");if(w.getBreakRevision()!=r.revision())throw new ApiException(HttpStatus.CONFLICT,"휴게 기록이 변경됐어요. 다시 조회해주세요");if(r.breaks()==null||r.breaks().size()>20)throw new ApiException(HttpStatus.BAD_REQUEST,"휴게 구간은 최대 20개로 입력해주세요");var list=new ArrayList<>(r.breaks());if(list.stream().anyMatch(b->b==null||b.from()==null||b.to()==null))throw new ApiException(HttpStatus.BAD_REQUEST,"휴게 시작·종료를 입력해주세요");list.sort(Comparator.comparing(StatutoryPayCalculator.Pause::from));LocalDateTime last=w.getClockIn(),end=w.getClockOut()==null?LocalDateTime.now():w.getClockOut();long seconds=0;for(var b:list){if(!b.to().isAfter(b.from())||b.from().isBefore(last)||b.to().isAfter(end)||b.from().getNano()!=0||b.to().getNano()!=0)throw new ApiException(HttpStatus.BAD_REQUEST,"휴게 구간은 근무시간 안에서 겹치지 않게 입력해주세요");seconds+=Duration.between(b.from(),b.to()).getSeconds();last=b.to();}if(seconds>=Duration.between(w.getClockIn(),end).getSeconds()&&!list.isEmpty())throw new ApiException(HttpStatus.BAD_REQUEST,"전체 근무시간을 휴게로 등록할 수 없어요");try{String value=json.writeValueAsString(list);if(!value.equals(w.getBreaksJson()))w.breaks(value,seconds,list.isEmpty()?null:last);}catch(Exception e){throw new IllegalStateException(e);}return view(w);}
}
